    function ProofServerStatus() {
        const { connectedApi, status } = useWallet();
        const [isOnline, setIsOnline] = reactExports.useState(null);
        reactExports.useEffect(()=>{
            if (status !== "connected" || !connectedApi) {
                setIsOnline(null);
                return;
            }
            let cancelled = false;
            async function check() {
                try {
                    const config = await connectedApi.getConfiguration();
                    const proofServerUrl = config.substrateNodeUri.replace(/\/rpc$/, "").replace(/:9944/, ":6300");
                    const response = await fetch(proofServerUrl, {
                        mode: "no-cors"
                    });
                    if (!cancelled) setIsOnline(response.type === "opaque" || response.ok);
                } catch  {
                    if (!cancelled) setIsOnline(false);
                }
            }
            check();
            return ()=>{
                cancelled = true;
            };
        }, [
            connectedApi,
            status
        ]);
        if (isOnline === null) return null;
        return jsxRuntimeExports.jsxs(Badge, {
            variant: isOnline ? "secondary" : "destructive",
            children: [
                "Proof Server: ",
                isOnline ? "Online" : "Offline"
            ]
        });
    }
